function maxBalancedSubsequenceSum(nums) {
  const n = nums.length;
  const keys = [...new Set(nums.map((value, i) => value - i))].sort((a, b) => a - b);
  const rank = new Map(keys.map((key, index) => [key, index + 1]));
  const tree = new Array(keys.length + 1).fill(0);
  let best = -Infinity;

  for (let i = 0; i < n; i++) {
    const position = rank.get(nums[i] - i);
    let before = 0;
    for (let p = position; p > 0; p -= p & -p) {
      before = Math.max(before, tree[p]);
    }
    const sum = nums[i] + before;
    best = Math.max(best, sum);
    for (let p = position; p < tree.length; p += p & -p) {
      tree[p] = Math.max(tree[p], sum);
    }
  }
  return best;
}

