function maxBalancedSubsequenceSum(nums) {
  // Try every non-empty set of indices and keep the balanced ones.
  const n = nums.length;
  let best = -Infinity;
  for (let mask = 1; mask < (1 << n); mask++) {
    let last = -1;
    let total = 0;
    let ok = true;
    for (let i = 0; i < n; i++) {
      if (!(mask >> i & 1)) continue;
      if (last >= 0 && nums[i] - nums[last] < i - last) ok = false;
      total += nums[i];
      last = i;
    }
    if (ok && total > best) best = total;
  }
  return best;
}

