function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const n = pick(1500, 2000);
    const mode = Math.floor(rand() * 3);
    if (mode === 0) return [Array.from({ length: n }, () => pick(-1000000000, 1000000000))];
    // Values that climb with the index (plus noise) give long balanced chains.
    const step = pick(1, 400000);
    return [Array.from({ length: n }, (_, i) => Math.max(-1000000000, Math.min(1000000000, -400000000 + i * step + pick(-3 * step, 3 * step))))];
  }
  const n = pick(1, 12);
  const span = [3, 10, 1000000000][Math.floor(rand() * 3)];
  if (rand() < 0.4) {
    const step = pick(0, 3);
    return [Array.from({ length: n }, (_, i) => Math.max(-span, Math.min(span, i * step - pick(0, span) + pick(0, span))))];
  }
  return [Array.from({ length: n }, () => pick(-span, span))];
}
